         ('BT MAINTENANCE MECANIQUE'),
         ('BT MAINTENANCE MOTEUR MACHINE MARINE'),
         ('BT MAINTENANCE VEHICULE ET ENGIN'),
         ('BT MECANIQUE AUTOMOBILE'),
         ('BT MENUISERIE EBENESTERIE'),
         ('BT OPTION COMPTABILITE'),
         ('BT PECHE'),
         ('BT SECRETARIAT BUREAUTIQUE'),
         ('BT SIENCE MEDICO SOCIAL'),
         ('BT TECHNICIEN BATIMENT'),
         ('BT TECHNIQUES HOTELLERIE'),
         ('BT TOPOGRAPHIE'),
