         ('BTS MAINTENANCE SYSTEMES DE PRODUCTION'),
         ('BTS RHCOM'),
         ('BTS RIT'),
         ('LICENCE')
       ) as d(nom)
 where not exists (
         select 1 from scolarite.diplomes x
          where upper(x.nom) = upper(d.nom)
       )
 order by upper(d.nom);


