   and upper(a.prenom) = upper(m.prenom)
   and a.date_naissance = m.naissance::date
   and a.classe_id in (
         select c.id
           from scolarite.classes c
           join scolarite.promotions p on p.id = c.promotion_id
          where upper(c.nom) = 'FCB'
            and p.nom like '37%'
       )
